import{_ as s,C as i,o,c as d,a2 as t,E as n}from"./chunks/framework.s9DbENeS.js";const m=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1794991345000}'),r={name:"guide/getting-started.md"};function l(c,e,h,p,u,g){const a=i("SetupBuilder");return o(),d("div",null,[e[0]||(e[0]=t(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>Create a new Ktor and SvelteKit project with everything wired up, and run it. It takes one command and a couple of minutes.</p><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><ul><li>Java 17 or newer</li><li>One of Bun, pnpm, npm or Yarn on your <code>PATH</code></li></ul><p>That is all. The setup script brings its own Gradle wrapper and always uses the latest ktor-svelte release.</p><h2 id="_1-create-the-project" tabindex="-1">1. Create the project <a class="header-anchor" href="#_1-create-the-project" aria-label="Permalink to &quot;1. Create the project&quot;">​</a></h2><p><strong>macOS and Linux:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/nijasc/ktor-svelte/main/scripts/setup.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><p><strong>Windows:</strong></p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">powershell </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;irm https://raw.githubusercontent.com/nijasc/ktor-svelte/main/scripts/setup.ps1 | iex&quot;</span></span></code></pre></div><p>It asks a few questions. Press Enter to take the defaults. Then it writes the project, installs the frontend, generates the TypeScript client and formats everything.</p><h2 id="_2-run-it" tabindex="-1">2. Run it <a class="header-anchor" href="#_2-run-it" aria-label="Permalink to &quot;2. Run it&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> svelteDevAll</span></span></code></pre></div><p>On Windows, run <code>gradlew.bat svelteDevAll</code>. If you chose Postgres, start it first with <code>docker compose up -d</code>.</p><p><code>svelteDevAll</code> starts Vite, the Kotlin compiler and your app, and opens <code>http://localhost:8080</code> once everything answers. <code>./gradlew dev</code> is short for the same task. In IntelliJ, open the folder and run the <code>Dev</code> configuration instead.</p><h2 id="_3-look-around" tabindex="-1">3. Look around <a class="header-anchor" href="#_3-look-around" aria-label="Permalink to &quot;3. Look around&quot;">​</a></h2><p>The first page of the new app lists what was set up for the answers you gave, each with a link to its docs, and what to do next. Try this:</p><ul><li>Edit <code>frontend/src/routes/+page.svelte</code> and save: the page updates without a reload.</li><li>Open <code>http://localhost:8080/api/hello</code>: that answer comes from <code>Application.kt</code>.</li><li>Click the <strong>API</strong> button in the corner of the page to see every call the app answers.</li><li>Change a route in Kotlin and save: the app restarts, and the typed client in <code>frontend/src/lib/api</code> follows.</li></ul><p>When something looks off, run <code>./gradlew svelteDoctor</code>.</p><h2 id="what-the-questions-mean" tabindex="-1">What the questions mean <a class="header-anchor" href="#what-the-questions-mean" aria-label="Permalink to &quot;What the questions mean&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Question</th><th>Flag</th><th>Default</th><th>What you get</th></tr></thead><tbody><tr><td>Project name, Kotlin package, package manager</td><td><code>--name</code>, <code>--package</code>, <code>--package-manager</code></td><td><code>my-app</code>, <code>com.example.app</code>, first one found</td><td></td></tr><tr><td>TypeScript client</td><td><code>--generate-ts</code></td><td>yes</td><td><code>generateTs</code> turned on</td></tr><tr><td>DaisyUI, Tailwind, Lucide</td><td><code>--daisy</code>, <code>--tailwind</code>, <code>--lucide</code></td><td>yes</td><td>Configured in <code>build.gradle.kts</code></td></tr><tr><td>i18n</td><td><code>--i18n</code>, <code>--locales</code>, <code>--locale-strategy</code></td><td>no</td><td>Message files and the chosen strategy</td></tr><tr><td>Sign in</td><td><code>--auth</code></td><td>no</td><td>Cookie sessions, hashed passwords, routes, and login and account pages</td></tr><tr><td>Postgres</td><td><code>--database</code></td><td>no</td><td>Exposed, HikariCP, <code>compose.yaml</code> and a small example table</td></tr><tr><td>Flyway, only with Postgres</td><td><code>--flyway</code></td><td>yes</td><td>Migrations in <code>src/main/resources/db/migration</code>, and <a href="./dev-workflow#generate-a-migration"><code>generateMigrations</code></a> to write the next one from your tables</td></tr><tr><td>No package folders</td><td><code>--idea-ext</code></td><td>yes</td><td>Kotlin files directly in <code>src/main/kotlin</code>, and IntelliJ knows the package through the <code>idea-ext</code> plugin</td></tr><tr><td>Convention plugin</td><td><code>--conventions</code></td><td>no</td><td><code>build-logic</code> with shared Kotlin and ktlint setup, for multi-module projects</td></tr><tr><td>Dockerfile</td><td><code>--docker</code></td><td>yes</td><td>A multi-stage build that runs the JAR as a non-root user</td></tr><tr><td>GitHub Actions</td><td><code>--github-actions</code></td><td>yes</td><td>A CI workflow with Actions pinned to commit SHAs</td></tr><tr><td>Git repository, only if git is installed</td><td><code>--git</code></td><td>yes</td><td><code>git init</code></td></tr><tr><td>IntelliJ live templates</td><td><code>--live-templates</code></td><td>yes</td><td>Installs <code>ksget</code>, <code>ksapi</code> and the other ktor-svelte live templates into every IntelliJ IDEA and WebStorm on the machine</td></tr><tr><td>Open in IntelliJ, only if it is installed</td><td><code>--open-idea</code></td><td>yes, but no with <code>--yes</code></td><td>Opens the project when it is ready</td></tr></tbody></table><p>DaisyUI includes Tailwind, so with <code>--daisy</code> the Tailwind question is skipped. The languages for i18n are written default first, such as <code>en,de</code>, and the strategy is <code>Cookie</code> or <code>UrlPrefix</code>.</p><p>Every project also gets a Gradle version catalog, JSON and typed error responses, ktlint, ESLint and Prettier, a <code>README.md</code>, a <code>.env.example</code> and a <code>.gitignore</code>. With sign in or Postgres, it also gets a <code>.env</code> with random secrets, which is not committed. <a href="./project-structure">Project structure</a> shows where everything lives.</p><h2 id="build-the-command" tabindex="-1">Build the command <a class="header-anchor" href="#build-the-command" aria-label="Permalink to &quot;Build the command&quot;">​</a></h2><p>Pick what you want, and copy the command for your system. It skips every question.</p>`,25)),n(a),e[1]||(e[1]=t('<p>To write the command by hand, add <code>--yes</code> and any options from the table. <code>--yes</code> takes the default for every question you do not answer with a flag. Turn something off with <code>--no-</code>, such as <code>--no-lucide</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/nijasc/ktor-svelte/main/scripts/setup.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name=shop</span></span></code></pre></div><p>On Windows, <code>irm ... | iex</code> cannot pass options, so run the script as a script block. Put options that contain a comma, such as <code>--locales=en,de</code>, in single quotes, or PowerShell splits them:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">powershell </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&amp; ([scriptblock]::Create((irm https://raw.githubusercontent.com/nijasc/ktor-svelte/main/scripts/setup.ps1))) --yes --name=shop --i18n &#39;--locales=en,de&#39;&quot;</span></span></code></pre></div><details class="details custom-block"><summary>Pin a release</summary><p>The script uses the latest release from Maven Central. Pass a release number, such as <code>--version=1.0.0</code>, to create the project with that release instead.</p></details><div class="tip custom-block"><p class="custom-block-title">Read before you run</p><p>Prefer to read scripts before running them? They are in <a href="https://github.com/nijasc/ktor-svelte/tree/main/scripts" target="_blank" rel="noreferrer"><code>scripts/</code></a>. <a href="./../security#what-runs-on-your-machine">What runs on your machine</a> explains what they download.</p></div><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Build something real: the <a href="./tutorial">tutorial</a> takes you from an empty project to a notes app in one JAR.</li><li>See every feature at a glance: <a href="./../features/">Everything ktor-svelte does</a>.</li><li>Already have an app? <a href="./existing-project">Add to an existing project</a>.</li><li>Tick settings in a form: the <a href="./configurator">Configurator</a>.</li></ul>',8))])}const y=s(r,[["render",l]]);export{m as __pageData,y as default};
